CREATE proc [dbo].[uspGetAccountSummaryNotBetweenDateFromTo] @DateFrom as datetime,@DateTo as datetime,@CAId as nvarchar(max) as select ca.CAId,ca.AccNature as AccountType,(select AccName from ChartOfAccount where CAId = (select ParentId from ChartOfAccount where CAId = ca.ParentId)) as Check_Group,(select AccName from ChartOfAccount where CAId = ca.ParentId) as SubGroup,ca.AccName as Account,ca.AccNo as Account_No,'' as AccType,convert(varchar,null,110) as Date,Cast(null as decimal(18,2)) as Amount,'' as [Type],'' as Description,isnull([dbo].uspGetNetOpenBalanceFunc(ca.CAId,ca.COId,@DateTo),0) as OpeningBalance,Cast(null as decimal(18,2)) as Credit,Cast(null as decimal(18,2)) as Debit,Cast(null as decimal(18,2)) as Balance,ca.[Level],ca.ParentId,ca.COId,'' as ChequeNum,convert(varchar,@DateFrom,110) as DateFrom,convert(varchar,@DateTo,110) as DateTo,'' as A,'' as B,'' as C,'' as D,'' as E,Cast('0' as decimal(18,2)) as A1,Cast('0' as decimal(18,2)) as A2,Cast('0' as decimal(18,2)) as A3,Cast('0' as decimal(18,2)) as A4,Cast('0' as decimal(18,2)) as A5,@DateTo as [DateTime] from ChartOfAccount ca inner join Split(@CAId,',') sp on sp.items = ca.CAId order by ca.AccName